head.script:
scwin.dbClick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.checkEL = function(id) {
    if (WebSquare.wUnit.getJq(id).css("display") == "block") {
        return true;
    }
    return false;
}
scwin.isIE = function() {
    var myNav = navigator.userAgent.toLowerCase();
    return (myNav.indexOf('msie') != -1) ? parseInt(myNav.split('msie')[1]) : false;
}
scwin.__isCheck = function() {
    if (scwin.isIE() && (scwin.isIE() == 11)) {
        return WebSquare.wUnit.getJq("#G_gridView1___autoComplete_2_col2_col2_itemTable").css("display") == "block";
    }
    return true;
}
scwin.setSimulate = function() {
    WebSquare.wUnit.getJq('#G_gridView1___autoComplete_2_col2_col2_input').simulate('key-sequence', {
        sequence: '1'
    });
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq('#G_'+$p.id+'gridView1___autoComplete_2_col2_col2_label').text() == '1';
}
scwin.unitTest = function() {
    // Int test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. Source 탭 또는 Property 에서 name2 컬럼의 cell 의 inputType 을 확인한다.- 1. In the Source tab or Property, check the inputType of the cell in the name2 column.
    //Verify 1. inputType='autoComplete'
    //Test step 4. 브라우저에서 readOnly 를 해제설정한 마지막 cell 을 더블클릭 후 '1' 을 입력한다.(name2항목의 3번째 컬럼)- Double-click the last cell in the browser that has readOnly disabled and enter '1'.(the third column of the name2 entry)
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView1_cell_2_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 4. 입력한 '1' 에 대해서 autoComplete 된다.- AutoComplete for '1' entered.
    WebSquare.wUnit.addCommand("assert", "scwin.checkEL('#G_'+$p.id+'gridView1___autoComplete_2_col2_col2_input')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "scwin.__isCheck()", "true");
    WebSquare.wUnit.addCommand("pause", "2500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop unitTest
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
        "value": "1",
        "label": "1"
    }, {
        "value": "2",
        "label": "2"
    }];
    dl_auto.setJSON(jsonData);
    window.jsonData2 = [{
        "col1": "a1",
        "col2": "1"
    }, {
        "col1": "a2",
        "col2": "1"
    }, {
        "col1": "a3",
        "col2": "1"
    }];
    dataList1.setJSON(jsonData2);
    gridView1.setCellReadOnly(2, 1, false);
    //Function unitTest
    //Create by Truong.Luu
    //Create date 23-Jan-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
